use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let data = input.as_array().unwrap();
    let mut ids = Vec::new();
    for pair in data {
        let priority = pair[0].as_i64().unwrap();
        let id = pair[1].as_i64().unwrap();
        ids.push(id);
    }
    ids.sort_by(|a, b| b.cmp(a));
    ids.into()
}
